# Analyze exact blocking behavior
# The rule appears to be:
# 1. Each L-shape gets a center point (midpoint of its bounding box)
# 2. From each center, draw a horizontal and vertical line
# 3. Stop drawing if you encounter ANY non-zero cell in the ORIGINAL input grid
# 4. Later colors don't overwrite earlier ones (no cross-color overwrites)
# 5. Same-color lines overlap seamlessly

def get_L_shape_center(grid):
    h, w = len(grid), len(grid[0])
    # Find all 3x3 corners for each color
    # For demo: 8 has corner at (4,6)-(6,8), center is (5,7)
    #            7 has corner at (10,12)-(12,14), center is (11,13)

    centers = {}
    for r in range(h - 2):
        for c in range(w - 2):
            subgrid = [row[c:c+3] for row in grid[r:r+3]]
            for dr in range(3):
                for dc in range(3):
                    val = subgrid[dr][dc]
                    if val > 0:
                        # Check if this could be part of a 3x3 line
                        pass

    # Simpler: find 3x3 blocks that have >= 3 cells of same color
    for r in range(h - 2):
        for c in range(w - 2):
            counts = {}
            for dr in range(3):
                for dc in range(3):
                    val = grid[r+dr][c+dc]
                    if val > 0:
                        counts[val] = counts.get(val, 0) + 1

            for color, cnt in sorted(counts.items()):
                if cnt >= 3:
                    cr, cc = r + 1, c + 1  # center of 3x3
                    centers.setdefault(color, []).append((cr, cc))

    return centers

