# Refined rule: check against ORIGINAL grid, not result
def transform_grid_v3(grid, centers_dict):
    result = [row[:] for row in grid]  # Copy of original
    # For each color center, determine expansion points based on ORIGINAL grid

    # First pass: mark all cells that will be expanded (based on original grid)
    expand_points = {}  # (color, r, c) -> set of cells to change
    for color in sorted(centers_dict.keys()):
        for cr, cc in centers_dict[color]:
            expand_points.setdefault(color, set())
            # Mark all cells in row cr
            for c in range(len(grid[cr])):
                if grid[cr][c] == 0:  # Only expand into empty cells
                    expand_points[color].add((cr, c))
            # Mark all cells in col cc
            for r in range(len(grid)):
                if grid[r][cc] == 0:  # Only expand into empty cells
                    expand_points[color].add((r, cc))

    # Second pass: apply expansions in ascending color order
    for color in sorted(expand_points.keys()):
        for r, c in expand_points[color]:
            # Only update if no later color claims this cell
            # Check if any later color's expansion includes this cell
            conflict = False
            for later_color in sorted(centers_dict.keys())[sorted(centers_dict.keys()).index(color)+1:]:
                for cr, cc in centers_dict[later_color]:
                    if (cr, c) == (r, c) or (r, cc) == (r, c):
                        conflict = True
                        break
                if conflict:
                    break
            if not conflict:
                result[r][c] = color

    return result

