def find_perfect_3x3s(grid):
    """Find all perfect 3x3 squares of a single color"""
    h, w = len(grid), len(grid[0])
    centers = set()  # Set of center positions

    for r in range(h - 2):
        for c in range(w - 2):
            # Check if this is a perfect 3x3 of a single color
            color = None
            valid = True
            for dr in range(3):
                for dc in range(3):
                    val = grid[r+dr][c+dc]
                    if val != 0:
                        if color is None:
                            color = val
                        elif val != color:
                            valid = False
                            break
                if not valid:
                    break

            if valid and color:
                # Perfect 3x3 of color at position (r,c)
                # Center is at (r+1, c+1)
                centers.add((r + 1, c + 1))

    return centers

