def is_perfect_3x3(grid, start_r, start_c):
    """Check if grid[start_r:start_r+3][start_c:start_c+3] is perfect 3x3 of one color"""
    h, w = len(grid), len(grid[0])
    if start_r + 2 >= h or start_c + 2 >= w:
        return False

    # Find the non-zero color
    color = None
    for dr in range(3):
        for dc in range(3):
            val = grid[start_r + dr][start_c + dc]
            if val != 0:
                if color is None:
                    color = val
                elif val != color:
                    return False

    if color:
        # All cells must be this color (including zeros which don't matter)
        for dr in range(3):
            for dc in range(3):
                val = grid[start_r + dr][start_c + dc]
                if val > 0 and val != color:
                    return False
        return True
    return False

